import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu from './components/Menu';
import Hud, { Toast } from './components/Hud';
import { GoalBanner, PauseMenu, Results } from './components/Overlays';
import { Game, HudState, MatchResult } from './game/engine';
import { diffById, loadSave, SaveData, storeSave } from './game/config';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';
const EMPTY: HudState = { score: [0, 0], clock: 120, charge: 0, stamina: 1, hasBall: true, turbo: 0, fire: false, giant: 0, level: 1, state: 'play', poss: 50 };

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null), gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu'), screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY);
  const [save, setSave] = useState<SaveData>(() => loadSave()), saveRef = useRef(save);
  const [result, setResult] = useState<{ r: MatchResult; record: boolean } | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [goal, setGoal] = useState<{ id: number; team: number; scorer: string } | null>(null);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const timers = useRef<number[]>([]), uid = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };
  const later = (fn: () => void, ms: number) => { timers.current.push(window.setTimeout(fn, ms)); };

  useEffect(() => {
    const host = hostRef.current; if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onToast: (text, color) => {
        const id = ++uid.current;
        setToasts(t => [...t.slice(-2), { id, text, color }]);
        later(() => setToasts(t => t.filter(x => x.id !== id)), 1600);
      },
      onGoal: (team, scorer) => {
        const id = ++uid.current; setGoal({ id, team, scorer });
        later(() => setGoal(g => (g && g.id === id ? null : g)), 3200);
        if (team === 0) {
          try { confetti({ particleCount: 140, spread: 110, origin: { y: 0.4 }, colors: ['#1f6dff', '#ffffff', '#c6ff3d', '#ffd23f'] }); } catch { /* sin confeti */ }
        }
      },
      onEnd: r => {
        const prev = saveRef.current, diff = r.score[0] - r.score[1], win = diff > 0;
        const record = win && diff > prev.bestDiff;
        persist({ ...prev, played: prev.played + 1, wins: prev.wins + (win ? 1 : 0), goals: prev.goals + r.score[0], bestDiff: Math.max(prev.bestDiff, diff) });
        later(() => {
          setResult({ r, record }); go('over');
          if (win) { try { confetti({ particleCount: 200, spread: 140, origin: { y: 0.3 } }); } catch { /* sin confeti */ } }
        }, 1400);
      },
    });
    game.toAttract();
    gameRef.current = game;
    return () => { timers.current.forEach(t => window.clearTimeout(t)); timers.current = []; game.dispose(); gameRef.current = null; };
  }, []);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init();
    (document.activeElement as HTMLElement | null)?.blur?.();
    setToasts([]); setGoal(null); setResult(null);
    const s = saveRef.current;
    setHud({ ...EMPTY, clock: s.dur });
    g.newMatch(diffById(s.diff), s.dur);
    go('play');
  }, []);

  const toMenu = useCallback(() => { gameRef.current?.toAttract(); setToasts([]); setGoal(null); go('menu'); }, []);

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p); go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.code !== 'Escape' && e.code !== 'KeyP') return;
      if (screenRef.current === 'play') setPaused(true); else if (screenRef.current === 'pause') setPaused(false);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };

  return (
    <div className="fa-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#0b1230]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="fa-vignette absolute inset-0" />
      {goal && goal.team === 0 && <div key={`f${goal.id}`} className="fa-flash absolute inset-0 bg-white" />}

      {screen === 'menu' && (
        <Menu save={save} muted={muted} onMute={toggleMute} onPlay={start}
          onDiff={id => { sound.click(); persist({ ...saveRef.current, diff: id }); }}
          onDur={s => { sound.click(); persist({ ...saveRef.current, dur: s }); }} />
      )}

      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} toasts={toasts} muted={muted} touch={touch} pad={gameRef.current.input.virtual}
          onPause={() => setPaused(true)} onMute={toggleMute} />
      )}
      {goal && screen === 'play' && <GoalBanner key={goal.id} team={goal.team} scorer={goal.scorer} />}

      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}
      {screen === 'over' && result && <Results r={result.r} record={result.record} onRetry={start} onMenu={toMenu} />}
    </div>
  );
}

import { useRef, type PointerEvent } from 'react';
import { Flame, Pause, Shield, Volume2, VolumeX, Zap } from 'lucide-react';
import { fmtClock, KITS } from '../game/config';
import { HudState } from '../game/engine';
import { VirtualPad } from '../game/input';

export interface Toast { id: number; text: string; color: string }
interface Props { hud: HudState; toasts: Toast[]; muted: boolean; touch: boolean; pad: VirtualPad; onPause(): void; onMute(): void }

function Scoreboard({ hud }: { hud: HudState }) {
  const low = hud.clock < 15 && hud.state === 'play';
  return (
    <div className="flex flex-col items-center">
      <div className="fa-board flex items-stretch overflow-hidden rounded-xl">
        {[0, 1].map(i => (
          <div key={i} className={`flex items-center gap-2 px-3 py-1.5 ${i ? 'flex-row-reverse border-l border-white/20' : ''}`}>
            <span className="h-6 w-1.5 rounded" style={{ background: KITS[i].ui, boxShadow: `0 0 10px ${KITS[i].ui}` }} />
            <span className="fa-display text-lg tracking-wide text-blue-100/90">{KITS[i].short}</span>
            <span className="fa-display min-w-[1.4ch] text-center text-3xl">{hud.score[i]}</span>
          </div>
        ))}
      </div>
      <div className={`fa-display -mt-px rounded-b-lg bg-[#c6ff3d] px-3 py-0.5 text-base leading-tight text-[#0b1230] ${low ? 'fa-pulse' : ''}`}>
        {fmtClock(hud.clock)}
      </div>
    </div>
  );
}

function Bar({ label, value, color }: { label: string; value: number; color: string }) {
  return (
    <div className="w-40 sm:w-52">
      <div className="mb-0.5 text-[10px] font-bold uppercase tracking-widest text-blue-100/70">{label}</div>
      <div className="h-2.5 overflow-hidden rounded-full bg-white/15">
        <div className="h-full rounded-full" style={{ width: `${Math.round(value * 100)}%`, background: color, boxShadow: `0 0 10px ${color}` }} />
      </div>
    </div>
  );
}

function Joystick({ pad }: { pad: VirtualPad }) {
  const base = useRef<HTMLDivElement>(null), knob = useRef<HTMLDivElement>(null);
  const move = (e: PointerEvent) => {
    const r = base.current!.getBoundingClientRect(), R = r.width / 2;
    let x = (e.clientX - r.left - R) / R, z = (e.clientY - r.top - R) / R;
    const l = Math.hypot(x, z); if (l > 1) { x /= l; z /= l; }
    pad.x = Math.abs(x) > 0.15 ? x : 0; pad.z = Math.abs(z) > 0.15 ? z : 0;
    knob.current!.style.transform = `translate(${x * R * 0.6}px, ${z * R * 0.6}px)`;
  };
  const end = () => { pad.x = 0; pad.z = 0; if (knob.current) knob.current.style.transform = ''; };
  return (
    <div ref={base} className="pointer-events-auto relative grid h-32 w-32 place-items-center rounded-full border border-white/25 bg-white/10"
      onPointerDown={e => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); move(e); }} onPointerMove={e => e.buttons && move(e)} onPointerUp={end} onPointerCancel={end}>
      <div ref={knob} className="h-14 w-14 rounded-full bg-white/70 shadow-lg" />
    </div>
  );
}

function TouchBtn({ label, color, size, onDown, onUp }: { label: string; color: string; size: number; onDown(): void; onUp?(): void }) {
  return (
    <button className="fa-display pointer-events-auto grid place-items-center rounded-full border-2 border-white/60 text-sm text-[#0b1230] shadow-lg active:scale-95"
      style={{ width: size, height: size, background: color }}
      onPointerDown={e => { e.preventDefault(); onDown(); }} onPointerUp={() => onUp?.()} onPointerLeave={() => onUp?.()}>{label}</button>
  );
}

export default function Hud({ hud, toasts, muted, touch, pad, onPause, onMute }: Props) {
  return (
    <div className="pointer-events-none absolute inset-0">
      <div className="absolute left-1/2 top-3 -translate-x-1/2"><Scoreboard hud={hud} /></div>
      <div className="pointer-events-auto absolute right-3 top-3 flex gap-2">
        <button onClick={onMute} aria-label="Silenciar" className="fa-chip grid h-10 w-10 place-items-center bg-black/30">{muted ? <VolumeX size={18} /> : <Volume2 size={18} />}</button>
        <button onClick={onPause} aria-label="Pausa" className="fa-chip grid h-10 w-10 place-items-center bg-black/30"><Pause size={18} /></button>
      </div>
      <div className="absolute left-3 top-3 flex flex-col gap-1.5">
        <div className="fa-board rounded-lg px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider">
          Rival · <span className="text-[#ff5a6a]">Nivel {hud.level}</span>
        </div>
        <div className="fa-board rounded-lg px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider text-blue-100/80">Posesión {hud.poss}%</div>
        {hud.turbo > 0 && <div className="fa-board flex items-center gap-1 rounded-lg px-2.5 py-1 text-xs font-bold text-[#ffe53b]"><Zap size={14} /> Turbo {Math.ceil(hud.turbo)}s</div>}
        {hud.fire && <div className="fa-board flex items-center gap-1 rounded-lg px-2.5 py-1 text-xs font-bold text-[#ff7a1a]"><Flame size={14} /> Tiro de fuego</div>}
        {hud.giant > 0 && <div className="fa-board flex items-center gap-1 rounded-lg px-2.5 py-1 text-xs font-bold text-[#3dff9a]"><Shield size={14} /> Portero gigante {Math.ceil(hud.giant)}s</div>}
      </div>

      <div className={`absolute flex flex-col gap-2 ${touch ? 'bottom-40 left-3' : 'bottom-4 left-4'}`}>
        <Bar label={hud.hasBall ? 'Potencia de tiro' : 'Potencia'} value={hud.charge} color={hud.charge > 0.85 ? '#ff5a1a' : '#ffd23f'} />
        <Bar label="Energía" value={hud.stamina} color="#3dd5ff" />
      </div>

      <div className="absolute left-1/2 top-[22%] flex -translate-x-1/2 flex-col items-center gap-2">
        {toasts.map(t => (
          <div key={t.id} className="fa-toast fa-display whitespace-nowrap rounded-lg bg-black/45 px-4 py-1 text-2xl" style={{ color: t.color, textShadow: `0 0 16px ${t.color}` }}>{t.text}</div>
        ))}
      </div>

      {touch && (
        <>
          <div className="absolute bottom-5 left-5"><Joystick pad={pad} /></div>
          <div className="absolute bottom-5 right-5 flex items-end gap-3">
            <div className="flex flex-col gap-3">
              <TouchBtn label="Sprint" color="#3dd5ff" size={60} onDown={() => { pad.sprint = true; }} onUp={() => { pad.sprint = false; }} />
              <TouchBtn label="Pase" color="#ffffff" size={68} onDown={() => { pad.pass = true; }} />
            </div>
            <TouchBtn label="Tiro" color="#c6ff3d" size={88} onDown={() => { pad.shoot = true; }} onUp={() => { pad.shoot = false; }} />
          </div>
        </>
      )}
    </div>
  );
}

import { Home, Play, RotateCcw, Trophy } from 'lucide-react';
import { KITS } from '../game/config';
import { MatchResult } from '../game/engine';

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume(): void; onRestart(): void; onMenu(): void }) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-[#040716]/70 p-4">
      <div className="fa-glass fa-rise w-full max-w-xs p-6 text-center">
        <div className="fa-display text-5xl">Pausa</div>
        <div className="mt-1 text-sm text-blue-100/60">El árbitro detiene el reloj</div>
        <div className="mt-5 flex flex-col gap-2">
          <button onClick={onResume} className="fa-btn fa-play fa-display flex items-center justify-center gap-2 py-3 text-xl"><Play size={20} fill="#0b1230" /> Continuar</button>
          <button onClick={onRestart} className="fa-btn fa-chip flex items-center justify-center gap-2 py-3 font-bold"><RotateCcw size={18} /> Reiniciar partido</button>
          <button onClick={onMenu} className="fa-btn fa-chip flex items-center justify-center gap-2 py-3 font-bold"><Home size={18} /> Menú principal</button>
        </div>
      </div>
    </div>
  );
}

export function GoalBanner({ team, scorer }: { team: number; scorer: string }) {
  const c = KITS[team].ui;
  return (
    <div className="pointer-events-none absolute inset-0 grid place-items-center">
      <div className="fa-goal text-center">
        <div className="fa-display text-[84px] leading-none sm:text-[150px]" style={{ color: '#fff', textShadow: `0 0 40px ${c}, 0 6px 0 ${c}` }}>¡Gooool!</div>
        <div className="fa-display mt-1 inline-block rounded-md px-4 py-1 text-xl sm:text-2xl" style={{ background: c }}>{KITS[team].name} · {scorer}</div>
      </div>
    </div>
  );
}

interface ResultProps { r: MatchResult; record: boolean; onRetry(): void; onMenu(): void }
export function Results({ r, record, onRetry, onMenu }: ResultProps) {
  const [a, b] = r.score;
  const title = a > b ? '¡Victoria!' : a < b ? 'Derrota' : 'Empate';
  const color = a > b ? '#c6ff3d' : a < b ? '#ff5a6a' : '#ffd23f';
  const rows: Array<[string, string, string]> = [
    ['Tiros', String(r.shots[0]), String(r.shots[1])],
    ['Posesión', `${r.poss}%`, `${100 - r.poss}%`],
  ];
  return (
    <div className="absolute inset-0 grid place-items-center bg-[#040716]/70 p-4">
      <div className="fa-glass fa-rise w-full max-w-sm p-6 text-center">
        <div className="text-xs font-bold uppercase tracking-[0.3em] text-blue-200/60">Final del partido</div>
        <div className="fa-display mt-1 text-6xl" style={{ color, textShadow: `0 0 24px ${color}` }}>{title}</div>
        {record && <div className="mx-auto mt-2 flex w-fit items-center gap-1 rounded-full bg-[#ffd23f] px-3 py-1 text-xs font-black uppercase text-[#0b1230]"><Trophy size={14} /> ¡Nuevo récord!</div>}
        <div className="mt-4 flex items-center justify-center gap-4">
          <span className="fa-display text-xl" style={{ color: KITS[0].ui }}>{KITS[0].short}</span>
          <span className="fa-display text-6xl">{a} – {b}</span>
          <span className="fa-display text-xl" style={{ color: KITS[1].ui }}>{KITS[1].short}</span>
        </div>
        <div className="mt-4 space-y-1 text-sm">
          {rows.map(([k, x, y]) => (
            <div key={k} className="flex justify-between rounded-lg bg-white/5 px-3 py-1.5"><b>{x}</b><span className="text-blue-100/60">{k}</span><b>{y}</b></div>
          ))}
        </div>
        <div className="mt-5 flex gap-2">
          <button onClick={onRetry} className="fa-btn fa-play fa-display flex flex-1 items-center justify-center gap-2 py-3 text-xl"><RotateCcw size={20} /> Revancha</button>
          <button onClick={onMenu} className="fa-btn fa-chip flex items-center justify-center gap-2 px-4 font-bold"><Home size={18} /> Menú</button>
        </div>
      </div>
    </div>
  );
}

import * as THREE from 'three';
import { FIELD } from './config';
import type { Match } from './match';
import type { Player } from './players';

// IA de compañeros, rivales y porteros: presión, apoyo, cobertura, regate, pase y tiro.
const { L, W, GW } = FIELD;
const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
const tmp = new THREE.Vector3();

/** Fija p.want hacia (x, z) con frenada suave al llegar. */
export function moveTo(p: Player, x: number, z: number, speed: number) {
  tmp.set(x - p.pos.x, 0, z - p.pos.z);
  const d = tmp.length();
  if (d < 0.15) { p.want.set(0, 0, 0); return; }
  p.want.copy(tmp).multiplyScalar(speed * Math.min(1, d / 1.6) / d);
}

function nearestOpponent(m: Match, p: Player) {
  let best: Player | null = null, bd = 1e9;
  for (const q of m.players) {
    if (q.team === p.team) continue;
    const d = q.pos.distanceTo(p.pos); if (d < bd) { bd = d; best = q; }
  }
  return { q: best, d: bd };
}

function keeper(m: Match, p: Player, speed: number) {
  const b = m.ball, dir = m.teams[p.team].dir, ownX = -dir * L;
  let tx = ownX + dir * 0.9, tz = clamp(b.pos.z * 0.45, -GW + 0.6, GW - 0.6);
  p.face.set(dir, 0, 0);
  if (!b.owner && b.vel.x * -dir > 4) {
    const th = (ownX - b.pos.x) / b.vel.x;
    if (th > 0 && th < 0.9) {
      tz = clamp(b.pos.z + b.vel.z * th, -GW - 0.4, GW + 0.4);
      const off = tz - p.pos.z;
      if (Math.abs(off) > 0.8 && th < 0.5 && p.dive <= 0 && Math.random() < 0.8) {
        p.dive = 0.65; p.diveSide = Math.sign(off * -p.face.x) || 1;
      }
    }
  }
  const inBox = Math.abs(b.pos.x - ownX) < FIELD.BOX_X && Math.abs(b.pos.z) < FIELD.BOX_Z;
  if (!b.owner && inBox && m.closestTo(b.pos, p.team, true) === p && b.speed < 9) { tx = b.pos.x; tz = b.pos.z; }
  if (b.owner && b.owner.team !== p.team && inBox) { tx = ownX + dir * 1.8; tz = clamp(b.owner.pos.z * 0.6, -GW, GW); }
  moveTo(p, tx, tz, speed * (p.dive > 0 ? 1.35 : 0.85));
}

function carry(m: Match, p: Player, speed: number, dt: number) {
  const dir = m.teams[p.team].dir, gx = dir * L;
  const dist = Math.hypot(gx - p.pos.x, p.pos.z), opp = nearestOpponent(m, p);
  const range = p.team === 1 ? m.diff.shootRange + m.level * 0.6 : 15;
  p.think -= dt;
  if (p.think <= 0) {
    p.think = 0.28;
    if (p.hold > 0.3 && dist < range && Math.random() < 0.5) { m.aiShoot(p); return; }
    if (opp.q && opp.d < 2.6 && p.hold > 0.25 && Math.random() < 0.45) { const mate = m.bestPass(p, null); if (mate) { m.pass(p, mate); return; } }
    if (Math.abs(p.pos.x - gx) < 3 && Math.random() < 0.6) { const mate = m.bestPass(p, null); if (mate) { m.pass(p, mate); return; } }
  }
  let tz = p.pos.z * 0.7;
  if (opp.q && opp.d < 4.5) tz = p.pos.z + (p.pos.z >= opp.q.pos.z ? 4 : -4);
  moveTo(p, gx - dir * 2, clamp(tz, -W + 2, W - 2), speed * 0.93);
}

export function aiThink(m: Match, p: Player, dt: number) {
  const b = m.ball, dir = m.teams[p.team].dir, speed = m.speedOf(p);
  if (p.role === 'gk') {
    if (b.owner === p) { p.want.set(0, 0, 0); if (p.hold > 0.9) { const mate = m.bestPass(p, null); if (mate) m.pass(p, mate); } return; }
    keeper(m, p, speed); return;
  }
  const owner = b.owner;
  if (owner === p) { carry(m, p, speed, dt); return; }
  if (owner && owner.team === p.team) {
    const ahead = p.role === 'att' ? 7 : -3;
    const tx = clamp(owner.pos.x + dir * ahead, -L + 3, L - 3);
    const tz = p.role === 'att' ? (owner.pos.z > 0 ? -6 : 6) : owner.pos.z * 0.35 + (owner.pos.z > 0 ? -3 : 3);
    moveTo(p, tx, tz, speed * 0.85); return;
  }
  const chaser = m.chaserOf(p.team);
  if (chaser === p) {
    tmp.copy(b.pos).addScaledVector(b.vel, owner ? 0.15 : 0.3);
    moveTo(p, tmp.x, tmp.z, speed);
    if (owner && owner.team !== p.team && owner.stun <= 0 && m.stateT > 1.2 && p.pos.distanceTo(owner.pos) < 1.15) {
      const rate = p.team === 1 ? m.diff.steal * (1 + m.level * 0.12) : 1.15;
      if (Math.random() < rate * dt) m.steal(p, owner);
    }
    return;
  }
  // Cobertura: entre el balón y la propia portería.
  const ownX = -dir * L, k = p.role === 'att' ? 0.75 : 0.45;
  const tx = ownX + (b.pos.x - ownX) * k, tz = b.pos.z * 0.55 + (p.role === 'att' ? (b.pos.z > 0 ? -4 : 4) : 0);
  moveTo(p, tx, clamp(tz, -W + 1, W - 1), speed * 0.8);
}

// Sonido con Web Audio API: silbato, golpes al balón, ambiente de grada y efectos.
class Sound {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private crowdGain: GainNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private muted = false;

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as any).webkitAudioContext;
      const ctx: AudioContext = new AC(); this.ctx = ctx;
      this.master = ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.55; this.master.connect(ctx.destination);
      const buf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate), d = buf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      this.noiseBuf = buf;
      // Murmullo continuo de la grada.
      const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
      const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 620; bp.Q.value = 0.5;
      this.crowdGain = ctx.createGain(); this.crowdGain.gain.value = 0;
      src.connect(bp); bp.connect(this.crowdGain); this.crowdGain.connect(this.master); src.start();
    } catch { this.ctx = null; }
  }
  setMuted(m: boolean) { this.muted = m; if (this.master) this.master.gain.value = m ? 0 : 0.55; }

  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slide = 0, delay = 0, vib = 0) {
    const c = this.ctx; if (!c || !this.master) return;
    const t = c.currentTime + delay, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t + dur);
    if (vib) {
      const l = c.createOscillator(), lg = c.createGain(); l.frequency.value = 32; lg.gain.value = vib;
      l.connect(lg); lg.connect(o.frequency); l.start(t); l.stop(t + dur);
    }
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.02);
  }
  private noise(dur: number, vol: number, freq: number, type: BiquadFilterType = 'lowpass', attack = 0.005, delay = 0) {
    const c = this.ctx; if (!c || !this.master || !this.noiseBuf) return;
    const t = c.currentTime + delay, s = c.createBufferSource(), f = c.createBiquadFilter(), g = c.createGain();
    s.buffer = this.noiseBuf; f.type = type; f.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t); s.stop(t + dur + 0.05);
  }

  kick(p: number) { this.tone(140, 0.14, 'sine', 0.5 + p * 0.3, 45); this.noise(0.07, 0.25 + p * 0.3, 2200); }
  touch() { this.tone(180, 0.06, 'sine', 0.2, 90); }
  whistle(n = 1) { for (let i = 0; i < n; i++) this.tone(2750, i === n - 1 ? 0.5 : 0.18, 'triangle', 0.22, 0, i * 0.26, 90); }
  post() { this.tone(1250, 0.5, 'triangle', 0.35, 900); this.tone(2600, 0.3, 'sine', 0.15, 2000); }
  save() { this.noise(0.12, 0.5, 900); this.tone(90, 0.15, 'sine', 0.4, 50); }
  tackle() { this.noise(0.25, 0.35, 1400, 'bandpass'); }
  pickup() { [660, 880, 1320].forEach((f, i) => this.tone(f, 0.16, 'square', 0.12, 0, i * 0.06)); }
  click() { this.tone(900, 0.05, 'square', 0.08); }
  cheer() {
    this.noise(3.2, 0.7, 900, 'bandpass', 0.35);
    this.noise(2.4, 0.3, 2400, 'bandpass', 0.2, 0.1);
    [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.35, 'sawtooth', 0.07, 0, 0.1 + i * 0.12));
  }
  groan() { this.noise(1.2, 0.4, 400, 'lowpass', 0.15); }
  /** Nivel del murmullo de la grada (0 = silencio). */
  crowd(level: number) {
    const c = this.ctx; if (!c || !this.crowdGain) return;
    this.crowdGain.gain.setTargetAtTime(Math.max(0, level) * 0.35, c.currentTime, 0.4);
  }
}

