import * as THREE from 'three';
import { BALL_R, FIELD } from './config';
import { canvasTexture, lin, radialTexture } from './three-compat';
import type { Player } from './players';

// Balón: física con gravedad, bote, rozamiento, postes/larguero, muros invisibles y detección de gol.
const { L, W, GW, GH, GD } = FIELD;
export type BallHit = 'none' | 'post' | 'goal+' | 'goal-' | 'wall';

export class Ball {
  readonly mesh: THREE.Mesh;
  readonly shadow: THREE.Mesh;
  readonly glow: THREE.Sprite;
  pos = new THREE.Vector3(0, BALL_R, 0);
  vel = new THREE.Vector3();
  owner: Player | null = null;
  last: Player | null = null;
  fire = 0;
  inGoal = 0;
  private axis = new THREE.Vector3();
  private q = new THREE.Quaternion();

  constructor(scene: THREE.Object3D) {
    const tex = canvasTexture(256, 128, g => {
      g.fillStyle = '#ffffff'; g.fillRect(0, 0, 256, 128);
      g.fillStyle = '#16182a';
      const spots = [[32, 30], [96, 64], [160, 30], [224, 64], [32, 98], [160, 98], [64, 64], [192, 64]];
      for (const [x, y] of spots) {
        g.beginPath();
        for (let i = 0; i < 5; i++) { const a = i * Math.PI * 0.4 - Math.PI / 2; g.lineTo(x + Math.cos(a) * 14, y + Math.sin(a) * 12); }
        g.fill();
      }
      g.fillRect(0, 0, 256, 6); g.fillRect(0, 122, 256, 6);
    });
    this.mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(BALL_R, 2), new THREE.MeshLambertMaterial({ map: tex, emissive: lin('#3a3a44') }));
    scene.add(this.mesh);
    this.shadow = new THREE.Mesh(new THREE.CircleGeometry(0.32, 16), new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.45, depthWrite: false }));
    this.shadow.rotation.x = -Math.PI / 2; scene.add(this.shadow);
    this.glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: radialTexture([[0, 'rgba(255,240,180,1)'], [0.35, 'rgba(255,140,30,0.7)'], [1, 'rgba(255,60,0,0)']]),
      blending: THREE.AdditiveBlending, depthWrite: false, transparent: true,
    }));
    this.glow.scale.set(2.2, 2.2, 1); this.glow.visible = false; scene.add(this.glow);
  }

  place(x: number, z: number) { this.pos.set(x, BALL_R, z); this.vel.set(0, 0, 0); this.owner = null; this.inGoal = 0; this.fire = 0; }
  get speed() { return Math.hypot(this.vel.x, this.vel.z); }

  step(dt: number): BallHit {
    const p = this.pos, v = this.vel;
    v.y -= 20 * dt;
    p.addScaledVector(v, dt);
    if (p.y < BALL_R) {
      p.y = BALL_R; v.y = v.y < -1.5 ? -v.y * 0.5 : 0;
      const f = Math.exp(-1.25 * dt); v.x *= f; v.z *= f;
    } else { const f = Math.exp(-0.15 * dt); v.x *= f; v.z *= f; }
    let hit: BallHit = 'none';
    const ax = Math.abs(p.x), sx = Math.sign(p.x) || 1;
    if (this.inGoal) { // dentro de la red
      if (ax > L + GD - BALL_R) { p.x = sx * (L + GD - BALL_R); v.x *= -0.15; }
      if (Math.abs(p.z) > GW - BALL_R) { p.z = Math.sign(p.z) * (GW - BALL_R); v.z *= -0.3; }
      if (p.y > GH - BALL_R) { p.y = GH - BALL_R; v.y *= -0.3; }
      return hit;
    }
    // Postes y larguero.
    for (const pz of [-GW, GW]) {
      const dx = p.x - sx * L, dz = p.z - pz, d = Math.hypot(dx, dz);
      if (d < BALL_R + 0.1 && p.y < GH + 0.1) {
        const nx = dx / d, nz = dz / d, dot = v.x * nx + v.z * nz;
        if (dot < 0) { v.x -= 1.7 * dot * nx; v.z -= 1.7 * dot * nz; hit = 'post'; }
        p.x = sx * L + nx * (BALL_R + 0.11); p.z = pz + nz * (BALL_R + 0.11);
      }
    }
    if (Math.abs(p.z) < GW && Math.abs(ax - L) < BALL_R + 0.1 && Math.abs(p.y - GH) < BALL_R + 0.1) {
      v.y = Math.abs(v.y) * 0.6 * Math.sign(p.y - GH || 1); v.x *= -0.6; hit = 'post';
    }
    const mouth = Math.abs(p.z) < GW - BALL_R * 0.5 && p.y < GH - BALL_R * 0.5;
    if (mouth && ax > L + BALL_R) { this.inGoal = sx; return sx > 0 ? 'goal+' : 'goal-'; }
    if (!mouth && ax > L + 0.6 - BALL_R) { p.x = sx * (L + 0.6 - BALL_R); v.x = -v.x * 0.6; hit = hit === 'none' ? 'wall' : hit; }
    if (Math.abs(p.z) > W + 1 - BALL_R) { p.z = Math.sign(p.z) * (W + 1 - BALL_R); v.z = -v.z * 0.6; hit = hit === 'none' ? 'wall' : hit; }
    return hit;
  }

  render(dt: number) {
    this.mesh.position.copy(this.pos);
    const sp = Math.hypot(this.vel.x, this.vel.z);
    if (sp > 0.05) {
      this.axis.set(this.vel.z, 0, -this.vel.x).normalize();
      this.q.setFromAxisAngle(this.axis, (sp / BALL_R) * dt);
      this.mesh.quaternion.premultiply(this.q);
    }
    this.shadow.position.set(this.pos.x, 0.03, this.pos.z);
    const s = Math.max(0.4, 1 - this.pos.y * 0.12); this.shadow.scale.set(s, s, s);
    this.glow.visible = this.fire > 0;
    this.glow.position.copy(this.pos);
  }
}

