import * as THREE from 'three';
import { FIELD } from './config';
import { STAND_END, STAND_FAR, FOG_HEX } from './stadium';
import { rawColor } from './three-compat';

// Público con InstancedMesh y un shader propio que los hace saltar y agitar (barato: todo en GPU).
const { L, W } = FIELD;
const SHIRTS = ['#1f6dff', '#1f6dff', '#3b82ff', '#ffffff', '#ff2e43', '#ff2e43', '#ffd23f', '#c6ff3d', '#2a2f45', '#8a5cff', '#ff8a3d'];
const SKINS = ['#f1c7a3', '#d9a27a', '#a8714c', '#7a4a2e', '#ffdcbf'];

const vert = `
attribute vec3 aCol; attribute float aSeed;
uniform float time; uniform float excite;
varying vec3 vCol; varying float vDepth; varying float vShade;
void main(){
  vec4 w = modelMatrix * instanceMatrix * vec4(position, 1.0);
  float jump = abs(sin(time * (5.0 + aSeed * 3.0) + aSeed * 40.0)) * excite * 0.45;
  float sway = sin(time * 1.7 + aSeed * 30.0) * 0.04;
  w.y += jump + sway;
  vec4 mv = viewMatrix * w;
  vDepth = -mv.z; vCol = aCol;
  vShade = 0.55 + 0.45 * clamp(position.y * 2.0 + 0.6, 0.0, 1.0);
  gl_Position = projectionMatrix * mv;
}`;
const frag = `
uniform vec3 fogCol; uniform float flash;
varying vec3 vCol; varying float vDepth; varying float vShade;
void main(){
  vec3 c = vCol * vShade * (0.85 + flash * 0.6);
  float f = smoothstep(60.0, 200.0, vDepth);
  gl_FragColor = vec4(mix(c, fogCol, f), 1.0);
}`;

export function buildCrowd(scene: THREE.Scene) {
  const seats: Array<{ p: THREE.Vector3; rot: number; team: number }> = [];
  for (let r = 0; r < 13; r++) for (let x = -L - 6; x <= L + 6; x += 0.78) {
    if (Math.random() < 0.06) continue;
    seats.push({ p: new THREE.Vector3(x + (Math.random() - 0.5) * 0.2, 0.6 + r * 0.55, -STAND_FAR - r * 0.85 - 0.42), rot: 0, team: x < 0 ? 0 : 1 });
  }
  for (const s of [-1, 1]) for (let r = 0; r < 10; r++) for (let z = -W - 3; z <= W + 3; z += 0.78) {
    if (Math.random() < 0.06) continue;
    seats.push({ p: new THREE.Vector3(s * (STAND_END + r * 0.85 + 0.42), 0.6 + r * 0.55, z + (Math.random() - 0.5) * 0.2), rot: s * Math.PI / 2, team: s < 0 ? 0 : 1 });
  }
  const n = seats.length;
  const uniforms = { time: { value: 0 }, excite: { value: 0.1 }, flash: { value: 0 }, fogCol: { value: rawColor(FOG_HEX) } };
  const mat = new THREE.ShaderMaterial({ uniforms, vertexShader: vert, fragmentShader: frag });
  const bodyGeo = new THREE.BoxGeometry(0.5, 0.75, 0.32); bodyGeo.translate(0, 0.38, 0);
  const headGeo = new THREE.BoxGeometry(0.26, 0.28, 0.26); headGeo.translate(0, 0.92, 0);
  const bCol = new Float32Array(n * 3), hCol = new Float32Array(n * 3), seed = new Float32Array(n);
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), sc = new THREE.Vector3(), up = new THREE.Vector3(0, 1, 0);
  const bodies = new THREE.InstancedMesh(bodyGeo, mat, n), heads = new THREE.InstancedMesh(headGeo, mat, n);
  seats.forEach((s, i) => {
    q.setFromAxisAngle(up, s.rot); const k = 0.9 + Math.random() * 0.22; sc.set(k, k, k);
    m.compose(s.p, q, sc); bodies.setMatrixAt(i, m); heads.setMatrixAt(i, m);
    const favour = Math.random() < 0.55 ? (s.team ? '#ff2e43' : '#1f6dff') : SHIRTS[(Math.random() * SHIRTS.length) | 0];
    const c = rawColor(favour), sk = rawColor(SKINS[(Math.random() * SKINS.length) | 0]);
    bCol.set([c.x, c.y, c.z], i * 3); hCol.set([sk.x, sk.y, sk.z], i * 3); seed[i] = Math.random();
  });
  bodyGeo.setAttribute('aCol', new THREE.InstancedBufferAttribute(bCol, 3));
  headGeo.setAttribute('aCol', new THREE.InstancedBufferAttribute(hCol, 3));
  bodyGeo.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seed, 1));
  headGeo.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seed.slice(), 1));
  for (const mesh of [bodies, heads]) { mesh.frustumCulled = false; mesh.instanceMatrix.needsUpdate = true; scene.add(mesh); }

  // Flashes de cámaras de fotos entre el público.
  const flashGeo = new THREE.BufferGeometry(), fp = new Float32Array(60 * 3);
  flashGeo.setAttribute('position', new THREE.BufferAttribute(fp, 3));
  const flashes = new THREE.Points(flashGeo, new THREE.PointsMaterial({ color: 0xffffff, size: 0.9, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }));
  flashes.frustumCulled = false; scene.add(flashes);

  let target = 0.1;
  return {
    /** 0 = tranquilo, 1 = euforia. */
    cheer(level: number) { target = Math.max(target, level); },
    update(dt: number, t: number) {
      uniforms.time.value = t;
      uniforms.excite.value += (target - uniforms.excite.value) * Math.min(1, dt * 4);
      target = Math.max(0.1, target - dt * 0.25);
      uniforms.flash.value = Math.max(0, uniforms.flash.value - dt * 2);
      const active = 6 + Math.floor(uniforms.excite.value * 50);
      for (let i = 0; i < 60; i++) {
        if (i < active && Math.random() < 0.3) {
          const s = seats[(Math.random() * n) | 0]; fp.set([s.p.x, s.p.y + 1.1, s.p.z], i * 3);
        } else fp[i * 3 + 1] = -50;
      }
      flashGeo.attributes.position.needsUpdate = true;
    },
    pulse() { uniforms.flash.value = 1; },
  };
}
export type Crowd = ReturnType<typeof buildCrowd>;

import * as THREE from 'three';
import { Difficulty, DIFFS, FIELD } from './config';
import { buildStadium, FOG_HEX, Stadium } from './stadium';
import { buildCrowd, Crowd } from './crowd';
import { Fx } from './fx';
import { Input } from './input';
import { Match, MatchState } from './match';
import { sound } from './audio';
import { LIGHT_K, lin, setupRenderer } from './three-compat';

// Motor: renderer, escena, luces, cámara de retransmisión, bucle y puente con React.
const { L } = FIELD;
const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));

export interface HudState {
  score: [number, number]; clock: number; charge: number; stamina: number; hasBall: boolean;
  turbo: number; fire: boolean; giant: number; level: number; state: MatchState; poss: number;
}
export interface MatchResult { score: [number, number]; shots: [number, number]; poss: number; diff: string }
export interface GameCallbacks {
  onHud(h: HudState): void;
  onToast(text: string, color: string): void;
  onGoal(team: number, scorer: string): void;
  onEnd(r: MatchResult): void;
}

export class Game {
  readonly input = new Input();
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(42, 1, 0.5, 900);
  private stadium: Stadium;
  private crowd: Crowd;
  private fx: Fx;
  private match: Match | null = null;
  private root: THREE.Group | null = null;
  private raf = 0;
  private ro: ResizeObserver;
  private last = performance.now();
  private t = 0; private hudT = 0; private fwT = 0;
  private shake = 0;
  private paused = false;
  private camPos = new THREE.Vector3(0, 20, 34);
  private camLook = new THREE.Vector3();

  constructor(private host: HTMLElement, private cb: GameCallbacks) {
    const r = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(r);
    r.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    r.domElement.style.cssText = 'display:block;width:100%;height:100%';
    host.appendChild(r.domElement);
    this.renderer = r;
    const s = this.scene;
    s.background = lin(FOG_HEX);
    s.fog = new THREE.Fog(lin(FOG_HEX), 85, 240);
    s.add(new THREE.HemisphereLight(lin('#a9bcff'), lin('#16301c'), 0.6 * LIGHT_K));
    s.add(new THREE.AmbientLight(lin('#ffffff'), 0.12 * LIGHT_K));
    const key = new THREE.DirectionalLight(lin('#fff4e2'), 0.95 * LIGHT_K); key.position.set(-25, 40, 30); s.add(key);
    const fill = new THREE.DirectionalLight(lin('#b9ccff'), 0.5 * LIGHT_K); fill.position.set(30, 32, -25); s.add(fill);
    const rim = new THREE.PointLight(lin('#c6ff3d'), 0.6 * LIGHT_K, 60, 2); rim.position.set(0, 10, -24); s.add(rim);
    this.stadium = buildStadium(s);
    this.crowd = buildCrowd(s);
    this.fx = new Fx(s);
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(host);
    this.resize();
    this.raf = requestAnimationFrame(this.loop);
  }

  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight);
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.fov = w / h < 1 ? 62 : 46;
    this.camera.updateProjectionMatrix();
  }

  private create(diff: Difficulty, dur: number, attract: boolean) {
    if (this.root) { this.disposeTree(this.root); this.scene.remove(this.root); }
    this.root = new THREE.Group(); this.scene.add(this.root);
    this.fx.clear();
    this.match = new Match(this.root, this.fx, {
      toast: (t, c) => this.cb.onToast(t, c),
      shake: a => { this.shake = Math.max(this.shake, a); },
      goal: (team, scorer) => {
        this.crowd.cheer(1); this.crowd.pulse(); this.stadium.shakeNet(team === 0 ? 1 : -1); this.fwT = 0;
        if (!attract) this.cb.onGoal(team, scorer);
      },
      end: () => {
        const m = this.match!; const total = m.teams[0].poss + m.teams[1].poss || 1;
        this.cb.onEnd({ score: [m.teams[0].score, m.teams[1].score], shots: [m.teams[0].shots, m.teams[1].shots], poss: Math.round(m.teams[0].poss / total * 100), diff: m.diff.id });
      },
    }, diff, dur, attract);
  }

  newMatch(diff: Difficulty, dur: number) { this.input.reset(); this.paused = false; this.create(diff, dur, false); }
  toAttract() { this.paused = false; this.create(DIFFS[1], 99999, true); sound.crowd(0.25); }
  setPaused(p: boolean) { this.paused = p; this.input.reset(); this.last = performance.now(); }

  private loop = (now: number) => {
    this.raf = requestAnimationFrame(this.loop);
    let dt = Math.min(0.05, (now - this.last) / 1000); this.last = now;
    if (this.paused) dt = 0;
    const m = this.match;
    if (m && m.state === 'goal' && m.stateT < 1) dt *= 0.4; // cámara lenta al marcar
    this.t += dt;
    if (m && dt > 0) {
      m.update(dt, m.attract ? null : this.input);
      if (Math.abs(m.ball.pos.x) > L - 12 && m.state === 'play') this.crowd.cheer(0.45);
      if (m.state === 'goal') {
        this.fwT -= dt;
        if (this.fwT <= 0) { this.fwT = 0.22; this.fx.firework(new THREE.Vector3((Math.random() - 0.5) * 70, 18 + Math.random() * 12, -28 - Math.random() * 10)); }
      }
      if (!m.attract) sound.crowd(0.25 + (Math.abs(m.ball.pos.x) > L - 12 ? 0.25 : 0) + (m.state === 'goal' ? 0.4 : 0));
    }
    this.stadium.update(dt);
    this.crowd.update(dt, this.t);
    this.fx.update(dt);
    if (m) this.updateCamera(m, dt);
    this.renderer.render(this.scene, this.camera);
    this.hudT -= dt;
    if (m && !m.attract && this.hudT <= 0 && dt > 0) { this.hudT = 0.08; this.emitHud(m); }
  };

  private updateCamera(m: Match, dt: number) {
    const b = m.ball.pos, pos = new THREE.Vector3(), look = new THREE.Vector3();
    let k = 2.6;
    if (m.attract) {
      const a = Math.sin(this.t * 0.1) * 0.9;
      pos.set(Math.sin(a) * 40 + b.x * 0.2, 15 + Math.sin(this.t * 0.17) * 3, Math.cos(a) * 34);
      look.set(b.x * 0.5, 0, b.z * 0.3 - 4); k = 1.2;
    } else if (m.state === 'goal' && m.scorer && m.stateT > 0.6) {
      const s = m.scorer.pos;
      pos.set(s.x - m.teams[m.scorer.team].dir * 3, 4.2, s.z + 9); look.set(s.x, 1.3, s.z); k = 2;
    } else if (m.state === 'over') {
      pos.set(Math.sin(this.t * 0.2) * 30, 22, 36); look.set(0, 0, -4); k = 1;
    } else {
      const cx = clamp(b.x * 0.92, -L + 9, L - 9);
      pos.set(cx, 14, clamp(b.z * 0.3, -6, 8) + 25); look.set(cx, 1.5, b.z * 0.6 - 4);
    }
    this.camPos.lerp(pos, Math.min(1, dt * k)); this.camLook.lerp(look, Math.min(1, dt * k * 1.3));
    this.shake = Math.max(0, this.shake - dt * 1.6);
    const sh = this.shake * this.shake * 1.2;
    this.camera.position.set(this.camPos.x + (Math.random() - 0.5) * sh, this.camPos.y + (Math.random() - 0.5) * sh, this.camPos.z);
    this.camera.lookAt(this.camLook);
  }

  private emitHud(m: Match) {
    const t0 = m.teams[0], total = t0.poss + m.teams[1].poss || 1;
    this.cb.onHud({
      score: [t0.score, m.teams[1].score], clock: m.clock, charge: m.charge, stamina: m.stamina,
      hasBall: !!m.human && m.ball.owner === m.human, turbo: t0.turbo, fire: t0.fire, giant: t0.giant,
      level: m.level, state: m.state, poss: Math.round(t0.poss / total * 100),
    });
  }

  private disposeTree(o: THREE.Object3D) {
    o.traverse(c => {
      const mesh = c as THREE.Mesh;
      if (mesh.geometry) mesh.geometry.dispose();
      const mat = mesh.material as THREE.Material | THREE.Material[] | undefined;
      (Array.isArray(mat) ? mat : mat ? [mat] : []).forEach(x => { const mm = x as THREE.MeshBasicMaterial; mm.map?.dispose(); x.dispose(); });
    });
  }

  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    this.input.dispose();
    sound.crowd(0);
    this.disposeTree(this.scene);
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

import * as THREE from 'three';
import { lin, radialTexture } from './three-compat';

// Partículas con pool fijo (Points aditivos): césped levantado, estela de fuego, fuegos artificiales, destellos.
const N = 700;

export class Fx {
  readonly points: THREE.Points;
  private pos = new Float32Array(N * 3);
  private col = new Float32Array(N * 3);
  private base = new Float32Array(N * 3);
  private vel = new Float32Array(N * 3);
  private life = new Float32Array(N);
  private max = new Float32Array(N);
  private grav = new Float32Array(N);
  private next = 0;
  private tmp = new THREE.Color();

  constructor(scene: THREE.Scene) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    g.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    for (let i = 0; i < N; i++) this.pos[i * 3 + 1] = -100;
    const mat = new THREE.PointsMaterial({
      size: 0.5, vertexColors: true, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
      map: radialTexture([[0, 'rgba(255,255,255,1)'], [0.4, 'rgba(255,255,255,0.6)'], [1, 'rgba(255,255,255,0)']], 32),
    });
    this.points = new THREE.Points(g, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
  }

  emit(p: THREE.Vector3, v: THREE.Vector3, color: string, life: number, grav = 1) {
    const i = this.next; this.next = (this.next + 1) % N;
    this.pos.set([p.x, p.y, p.z], i * 3); this.vel.set([v.x, v.y, v.z], i * 3);
    this.tmp.copy(lin(color)); this.base.set([this.tmp.r, this.tmp.g, this.tmp.b], i * 3);
    this.life[i] = life; this.max[i] = life; this.grav[i] = grav;
  }

  burst(p: THREE.Vector3, n: number, colors: string[], speed: number, up: number, life: number, grav = 1) {
    const v = new THREE.Vector3();
    for (let k = 0; k < n; k++) {
      v.set(Math.random() - 0.5, Math.random() * 0.6, Math.random() - 0.5).normalize().multiplyScalar(speed * (0.4 + Math.random() * 0.6));
      v.y += up * Math.random();
      this.emit(p, v, colors[k % colors.length], life * (0.6 + Math.random() * 0.6), grav);
    }
  }

  /** Cohete de fuegos artificiales sobre las gradas. */
  firework(p: THREE.Vector3) {
    const cols = [['#ffd23f', '#ffffff'], ['#3b82ff', '#9fd0ff'], ['#ff3b4f', '#ffc0c8'], ['#c6ff3d', '#ffffff']][(Math.random() * 4) | 0];
    const v = new THREE.Vector3();
    for (let k = 0; k < 60; k++) {
      v.set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5).normalize().multiplyScalar(7 + Math.random() * 3);
      this.emit(p, v, cols[k % 2], 1.3 + Math.random() * 0.5, 0.25);
    }
  }

  update(dt: number) {
    for (let i = 0; i < N; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      const j = i * 3;
      if (this.life[i] <= 0) { this.pos[j + 1] = -100; continue; }
      this.vel[j + 1] -= 14 * this.grav[i] * dt;
      const drag = Math.exp(-1.2 * dt);
      this.vel[j] *= drag; this.vel[j + 2] *= drag;
      this.pos[j] += this.vel[j] * dt; this.pos[j + 1] += this.vel[j + 1] * dt; this.pos[j + 2] += this.vel[j + 2] * dt;
      if (this.pos[j + 1] < 0.05 && this.grav[i] > 0.5) { this.pos[j + 1] = 0.05; this.vel[j + 1] *= -0.3; }
      const k = Math.min(1, (this.life[i] / this.max[i]) * 1.6);
      this.col[j] = this.base[j] * k; this.col[j + 1] = this.base[j + 1] * k; this.col[j + 2] = this.base[j + 2] * k;
    }
    const g = this.points.geometry;
    g.attributes.position.needsUpdate = true; g.attributes.color.needsUpdate = true;
  }

  clear() { this.life.fill(0); for (let i = 0; i < N; i++) this.pos[i * 3 + 1] = -100; }
}

// Entrada: teclado en window + controles táctiles virtuales (joystick y botones).
export interface VirtualPad { x: number; z: number; shoot: boolean; sprint: boolean; pass: boolean }

const GAME_KEYS = ['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'];

export class Input {
  private keys = new Set<string>();
  private edges = new Set<string>();
  readonly virtual: VirtualPad = { x: 0, z: 0, shoot: false, sprint: false, pass: false };
  private prevShoot = false;

  private onDown = (e: KeyboardEvent) => {
    if (GAME_KEYS.includes(e.code)) e.preventDefault();
    if (!this.keys.has(e.code)) this.edges.add(e.code);
    this.keys.add(e.code);
  };
  private onUp = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private onBlur = () => { this.keys.clear(); };

  constructor() {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }

  private any(...c: string[]) { return c.some(k => this.keys.has(k)); }
  /** Dirección de movimiento en el plano (x: derecha, z: hacia la cámara). */
  axis() {
    let x = (this.any('ArrowRight', 'KeyD') ? 1 : 0) - (this.any('ArrowLeft', 'KeyA') ? 1 : 0) + this.virtual.x;
    let z = (this.any('ArrowDown', 'KeyS') ? 1 : 0) - (this.any('ArrowUp', 'KeyW') ? 1 : 0) + this.virtual.z;
    const l = Math.hypot(x, z); if (l > 1) { x /= l; z /= l; }
    return { x, z };
  }
  get shootHeld() { return this.virtual.shoot || this.any('Space', 'KeyJ'); }
  get sprint() { return this.virtual.sprint || this.any('ShiftLeft', 'ShiftRight', 'KeyL'); }
  /** Flanco de bajada del tiro (pulsación nueva). */
  shootPressed() {
    const now = this.shootHeld, e = now && !this.prevShoot; return e;
  }
  passPressed() {
    const p = this.edges.has('KeyX') || this.edges.has('KeyK') || this.virtual.pass;
    this.virtual.pass = false; return p;
  }
  endFrame() { this.prevShoot = this.shootHeld; this.edges.clear(); }
  reset() { this.keys.clear(); this.edges.clear(); Object.assign(this.virtual, { x: 0, z: 0, shoot: false, sprint: false, pass: false }); }

  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

import * as THREE from 'three';
import { Ball } from './ball';
import { aiThink } from './ai';
import { BALL_R, Difficulty, FIELD, KITS, POWER_INFO, PowerKind } from './config';
import { Fx } from './fx';
import { Input } from './input';
import { Player, Role } from './players';
import { sound } from './audio';
import { lin, radialTexture } from './three-compat';
import { PowerUps } from './powerups';

// Reglas del partido: posesión, pases, tiros, porteros, robos, goles, reloj y control del jugador humano.
const { L, W, GW } = FIELD;
const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));

export interface TeamState { score: number; shots: number; poss: number; turbo: number; fire: boolean; giant: number; dir: number }
export interface MatchEvents {
  toast(text: string, color: string): void;
  goal(team: number, scorer: string): void;
  end(): void;
  shake(a: number): void;
}
export type MatchState = 'play' | 'goal' | 'over';

export class Match {
  players: Player[] = [];
  ball: Ball;
  teams: TeamState[] = [0, 1].map(i => ({ score: 0, shots: 0, poss: 0, turbo: 0, fire: false, giant: 0, dir: i ? -1 : 1 }));
  state: MatchState = 'play';
  stateT = 0;
  clock: number;
  level = 1;
  human: Player | null = null;
  charge = 0; charging = false; stamina = 1;
  scorer: Player | null = null;
  powerups: PowerUps;
  private switchCd = 0;
  private t = 0;
  private shadowMat: THREE.MeshBasicMaterial;

  constructor(private scene: THREE.Object3D, private fx: Fx, private ev: MatchEvents, public diff: Difficulty, readonly duration: number, readonly attract: boolean) {
    this.clock = duration;
    this.shadowMat = new THREE.MeshBasicMaterial({
      map: radialTexture([[0, 'rgba(0,0,0,0.55)'], [0.5, 'rgba(0,0,0,0.25)'], [1, 'rgba(0,0,0,0)']]),
      transparent: true, depthWrite: false, color: lin('#ffffff'),
    });
    const roles: Role[] = ['gk', 'def', 'att'];
    for (const team of [0, 1]) roles.forEach((r, i) => this.players.push(new Player(scene, team, r, KITS[team], i + 1, this.shadowMat)));
    this.ball = new Ball(scene);
    this.powerups = new PowerUps(scene);
    this.kickoff(0);
  }

  get gk() { return [0, 1].map(t => this.players.find(p => p.team === t && p.role === 'gk')!); }

  kickoff(team: number) {
    this.state = 'play'; this.stateT = 0; this.scorer = null;
    this.ball.place(0, 0);
    for (const p of this.players) {
      const d = this.teams[p.team].dir, own = p.team === team;
      const pos = p.role === 'gk' ? new THREE.Vector3(-d * (L - 0.9), 0, 0)
        : p.role === 'def' ? new THREE.Vector3(-d * 12, 0, own ? -4 : 5)
          : new THREE.Vector3(own ? -d * 0.65 : -d * 5.5, 0, own ? 0 : -1.5);
      p.reset(pos, d); p.home.copy(pos); p.scale = 1;
    }
    const taker = this.players.find(p => p.team === team && p.role === 'att')!;
    taker.kickCd = 0; this.ball.owner = taker; taker.hold = 0;
    if (!this.attract) this.setHuman(this.players.find(p => p.team === 0 && p.role === 'att')!);
    sound.whistle(1);
  }

  setHuman(p: Player) {
    if (this.human) this.human.marker.visible = false;
    this.human = p; p.marker.visible = true; this.switchCd = 0.6;
  }

  speedOf(p: Player) {
    let s = p.team === 1 ? this.diff.speed + this.level * 0.18 : 7.3;
    if (p.role === 'gk') s *= 0.85;
    if (p === this.human) s = this.stamina > 0.05 && p.sprinting ? 9.8 : 7.6;
    if (this.ball.owner === p) s *= 0.9;
    if (this.teams[p.team].turbo > 0) s *= 1.3;
    return s;
  }

  closestTo(pt: THREE.Vector3, team: number, includeGk: boolean) {
    let best: Player | null = null, bd = 1e9;
    for (const p of this.players) {
      if (p.team !== team || (!includeGk && p.role === 'gk') || p.stun > 0) continue;
      const d = p.pos.distanceTo(pt); if (d < bd) { bd = d; best = p; }
    }
    return best;
  }
  chaserOf(team: number) { return team === 0 && this.human ? this.human : this.closestTo(this.ball.pos, team, false); }

  // ---------- Acciones ----------
  private kick(p: Player, dx: number, dz: number, speed: number, lift: number) {
    const b = this.ball, l = Math.hypot(dx, dz) || 1;
    const fire = this.teams[p.team].fire && speed > 16;
    if (fire) { speed *= 1.3; lift *= 0.7; this.teams[p.team].fire = false; b.fire = 1; this.ev.shake(0.5); }
    b.owner = null; b.last = p; b.pos.y = BALL_R + 0.05;
    b.vel.set((dx / l) * speed, lift, (dz / l) * speed);
    p.kickCd = 0.32; p.kickAnim = 1; p.hold = 0;
    sound.kick(Math.min(1, speed / 30));
    this.fx.burst(b.pos, 10, ['#9dff8a', '#e2ffd0'], 3 + speed * 0.1, 3, 0.6);
  }

  shoot(p: Player, aimZ: number, power: number) {
    const gx = this.teams[p.team].dir * (L + 0.5);
    this.teams[p.team].shots++;
    this.kick(p, gx - p.pos.x, aimZ - p.pos.z, 15 + power * 15, 1.2 + power * 4);
    this.ev.shake(0.15 + power * 0.25);
  }

  aiShoot(p: Player) {
    const err = p.team === 1 ? this.diff.aim : 1.6;
    const side = Math.random() < 0.5 ? -1 : 1;
    this.shoot(p, side * (GW - 0.7) + (Math.random() - 0.5) * err * 2, 0.5 + Math.random() * 0.45);
  }

  pass(p: Player, mate: Player) {
    const lead = mate.pos.clone().addScaledVector(mate.vel, 0.4);
    const d = lead.distanceTo(p.pos);
    this.kick(p, lead.x - p.pos.x, lead.z - p.pos.z, clamp(7 + d * 1.05, 10, 22), d > 14 ? 3.2 : 0.8);
    mate.kickCd = 0;
  }

  bestPass(p: Player, pref: THREE.Vector3 | null) {
    let best: Player | null = null, bs = -1e9;
    const dir = this.teams[p.team].dir;
    for (const q of this.players) {
      if (q.team !== p.team || q === p) continue;
      const dx = q.pos.x - p.pos.x, dz = q.pos.z - p.pos.z, d = Math.hypot(dx, dz);
      let open = 9;
      for (const o of this.players) if (o.team !== p.team) open = Math.min(open, o.pos.distanceTo(q.pos));
      let s = open * 0.8 + dx * dir * 0.25 - Math.abs(d - 11) * 0.15 - (q.role === 'gk' ? 8 : 0);
      if (pref) s += ((dx * pref.x + dz * pref.z) / (d || 1)) * 9;
      if (s > bs) { bs = s; best = q; }
    }
    return best;
  }

  steal(thief: Player, victim: Player) {
    victim.stun = 0.75; victim.kickCd = 0.9; victim.hold = 0;
    this.ball.owner = thief; this.ball.last = thief; thief.hold = 0; thief.kickCd = 0;
    sound.tackle(); this.fx.burst(victim.pos.clone().setY(0.3), 14, ['#b8ff9a', '#ffffff'], 4, 3, 0.6);
    if (thief === this.human) this.ev.toast('¡Robo!', '#c6ff3d');
  }

  // ---------- Bucle ----------
  update(dt: number, input: Input | null) {
    this.t += dt; this.stateT += dt;
    const b = this.ball;
    for (const tm of this.teams) { tm.turbo = Math.max(0, tm.turbo - dt); tm.giant = Math.max(0, tm.giant - dt); }
    this.gk.forEach((g, i) => { g.scale += ((this.teams[i].giant > 0 ? 1.55 : 1) - g.scale) * Math.min(1, dt * 5); });

    if (this.state === 'play' && !this.attract) {
      this.clock -= dt;
      const lvl = Math.min(6, 1 + Math.floor((1 - this.clock / this.duration) * 3) + Math.max(0, this.teams[0].score - this.teams[1].score));
      if (lvl > this.level) this.ev.toast(`¡El rival aprieta! Nivel ${lvl}`, '#ff3b4f');
      this.level = lvl;
      if (this.clock <= 0) { this.clock = 0; this.state = 'over'; this.stateT = 0; sound.whistle(3); this.ev.end(); }
    }
    if (this.state === 'goal' && this.stateT > 3.6) {
      const conceded = this.scorer && this.scorer.team === 0 ? 1 : 0;
      this.kickoff(conceded);
    }

    // Decisiones.
    for (const p of this.players) {
      p.kickCd = Math.max(0, p.kickCd - dt); p.stun = Math.max(0, p.stun - dt); p.kickAnim = Math.max(0, p.kickAnim - dt * 3.3);
      p.dive = Math.max(0, p.dive - dt); p.celebrate = Math.max(0, p.celebrate - dt);
      if (b.owner === p) p.hold += dt;
      if (this.state !== 'play') {
        if (p.celebrate > 0 && this.scorer) { const s = this.scorer.pos; p.want.set((s.x - p.pos.x) * 0.8, 0, (s.z - p.pos.z) * 0.8); if (p === this.scorer) p.want.set(0, 0, 0); }
        else p.want.multiplyScalar(0.9);
        continue;
      }
      if (p === this.human && input) this.controlHuman(p, dt, input);
      else aiThink(this, p, dt);
      if (p.stun > 0) p.want.set(0, 0, 0);
    }
    if (input) input.endFrame();

    // Movimiento de jugadores.
    for (const p of this.players) {
      if (p.slide > 0) { p.slide = Math.max(0, p.slide - dt); if (p.slide === 0) p.stun = 0.2; p.vel.multiplyScalar(Math.exp(-2.2 * dt)); }
      else p.vel.lerp(p.want, Math.min(1, dt * (p.role === 'gk' ? 10 : 7)));
      p.pos.addScaledVector(p.vel, dt);
      p.pos.x = clamp(p.pos.x, -L - 0.4, L + 0.4); p.pos.z = clamp(p.pos.z, -W - 0.8, W + 0.8);
      const sp = Math.hypot(p.vel.x, p.vel.z);
      if (p.role !== 'gk' && sp > 0.5 && p.slide <= 0 && p.celebrate <= 0) {
        p.face.lerp(new THREE.Vector3(p.vel.x / sp, 0, p.vel.z / sp), Math.min(1, dt * 12)).normalize();
      }
      if (p.celebrate > 0) p.face.set(0, 0, 1);
    }
    for (let i = 0; i < this.players.length; i++) for (let j = i + 1; j < this.players.length; j++) {
      const a = this.players[i], c = this.players[j], dx = c.pos.x - a.pos.x, dz = c.pos.z - a.pos.z, d = Math.hypot(dx, dz);
      if (d > 0.01 && d < 0.75) { const k = (0.75 - d) / d * 0.5; a.pos.x -= dx * k; a.pos.z -= dz * k; c.pos.x += dx * k; c.pos.z += dz * k; }
    }

    this.updateBall(dt);
    const picked = this.powerups.update(dt, this.t, this.players, this.state === 'play');
    if (picked) this.applyPower(picked.kind, picked.p);
    for (const p of this.players) p.animate(dt, this.t);
  }

  private controlHuman(p: Player, dt: number, input: Input) {
    const b = this.ball, a = input.axis(), dir = this.teams[0].dir;
    p.sprinting = input.sprint && (a.x !== 0 || a.z !== 0) && this.stamina > 0.05;
    this.stamina = clamp(this.stamina + (p.sprinting ? -0.32 : 0.18) * dt, 0, 1);
    const s = this.speedOf(p);
    if (p.slide <= 0) p.want.set(a.x * s, 0, a.z * s);
    this.switchCd = Math.max(0, this.switchCd - dt);
    if (b.owner === p) {
      if (input.shootHeld) { this.charging = true; this.charge = Math.min(1, this.charge + dt * 1.6); }
      else if (this.charging) {
        const power = Math.max(0.3, this.charge), gx = dir * L;
        const toGoal = new THREE.Vector3(gx - p.pos.x, 0, -p.pos.z).normalize();
        if (p.face.dot(toGoal) > -0.1) {
          const gk = this.gk[1], aim = Math.abs(a.z) > 0.3 ? a.z : -(Math.sign(gk.pos.z - p.pos.z * 0.1) || 1);
          this.shoot(p, clamp(aim * GW * 0.8 + (Math.random() - 0.5) * 0.9, -GW + 0.3, GW - 0.3), power);
        }
        else this.kick(p, p.face.x, p.face.z, 14 + power * 12, 1 + power * 3);
        this.charging = false; this.charge = 0;
      }
      if (input.passPressed()) { const mate = this.bestPass(p, p.face); if (mate) this.pass(p, mate); }
      return;
    }
    this.charging = false; this.charge = 0;
    if (input.shootPressed() && p.slide <= 0 && p.stun <= 0) {
      p.slide = 0.45; p.vel.copy(p.face).multiplyScalar(12); sound.tackle();
    }
    if (input.passPressed()) {
      let best: Player | null = null, bd = 1e9;
      for (const q of this.players) if (q.team === 0 && q !== p && q.role !== 'gk') { const d = q.pos.distanceTo(b.pos); if (d < bd) { bd = d; best = q; } }
      if (best) { this.setHuman(best); sound.click(); }
    }
    if (p.slide > 0 && b.owner && b.owner.team !== 0 && p.pos.distanceTo(b.owner.pos) < 1.4) this.steal(p, b.owner);
    if (this.switchCd <= 0 && (!b.owner || b.owner.team !== 0)) {
      const c = this.closestTo(b.pos, 0, false);
      if (c && c !== p && c.pos.distanceTo(b.pos) + 2.5 < p.pos.distanceTo(b.pos)) this.setHuman(c);
    }
  }

  private updateBall(dt: number) {
    const b = this.ball, o = b.owner;
    if (o) {
      if (o === this.human || o.team === 0) { if (this.human && o.team === 0 && o !== this.human && o.role !== 'gk') this.setHuman(o); }
      this.teams[o.team].poss += dt;
      if (o.role === 'gk') b.pos.set(o.pos.x + o.face.x * 0.45, 1.1 * o.scale, o.pos.z + o.face.z * 0.45);
      else {
        const sp = Math.hypot(o.vel.x, o.vel.z), off = 0.58 + Math.abs(Math.sin(this.t * (2 + sp))) * 0.12 * Math.min(1, sp / 4);
        b.pos.set(o.pos.x + o.face.x * off, BALL_R, o.pos.z + o.face.z * off);
      }
      b.vel.copy(o.vel); b.vel.y = 0;
    } else {
      const hit = b.step(dt);
      if (hit === 'post') { sound.post(); this.ev.shake(0.2); this.ev.toast('¡Al palo!', '#ffffff'); }
      if (hit === 'goal+' || hit === 'goal-') this.onGoal(hit === 'goal+' ? 0 : 1);
      if (this.state === 'play' && !b.inGoal) this.tryControl();
    }
    if (b.fire > 0) {
      b.fire = b.speed > 6 ? b.fire : Math.max(0, b.fire - dt);
      const v = new THREE.Vector3((Math.random() - 0.5) * 2, 1.5, (Math.random() - 0.5) * 2);
      for (let i = 0; i < 2; i++) this.fx.emit(b.pos, v, i ? '#ffd23f' : '#ff5a1a', 0.45, -0.2);
    } else if (b.speed > 18 && !b.owner) this.fx.emit(b.pos, new THREE.Vector3(), '#cfe0ff', 0.3, 0);
    b.render(dt);
  }

  private tryControl() {
    const b = this.ball;
    for (const p of this.players) {
      if (p.kickCd > 0 || p.stun > 0) continue;
      const own = -this.teams[p.team].dir * L;
      const hands = p.role === 'gk' && Math.abs(b.pos.x - own) < FIELD.BOX_X + 0.5 && Math.abs(b.pos.z) < FIELD.BOX_Z;
      const reach = hands ? (0.9 + (p.dive > 0 ? 0.8 : 0)) * p.scale : 0.75 + (p.slide > 0 ? 0.5 : 0);
      const top = hands ? 2.3 * p.scale + (p.dive > 0 ? 0.4 : 0) : 1.0;
      const d = Math.hypot(b.pos.x - p.pos.x, b.pos.z - p.pos.z);
      if (d > reach || b.pos.y > top) continue;
      const fast = b.speed > 10 && b.last !== null && b.last.team !== p.team;
      if (hands && fast) {
        let chance = (p.team === 1 ? this.diff.save + this.level * 0.03 : 0.5) - (b.speed > 24 ? 0.15 : 0);
        if (this.teams[p.team].giant > 0) chance = 0.95;
        if (b.fire > 0) chance *= 0.3;
        const r = Math.random();
        if (r > chance + 0.22) { p.kickCd = 0.6; p.dive = Math.max(p.dive, 0.4); continue; } // ¡batido!
        if (r < chance) {
          b.owner = p; b.fire = 0; p.hold = 0; sound.save(); this.ev.toast(p.team === 1 ? '¡Paradón del portero!' : '¡Atajada!', p.team ? '#ffb21e' : '#3dff9a');
        } else {
          b.vel.set(-b.vel.x * 0.25, 4 + Math.random() * 3, (Math.sign(b.pos.z) || 1) * (7 + Math.random() * 5));
          b.fire = 0; p.kickCd = 1.1; this.ev.toast('¡Rechace!', '#ffffff'); b.last = p; sound.save(); this.ev.shake(0.2);
        }
        return;
      }
      if (!hands && fast && b.speed > 15) {
        const r = Math.random(); p.kickCd = 0.3;
        if (r < 0.55) continue; // el tiro pasa entre las piernas
        if (r < 0.8) { b.vel.multiplyScalar(-0.3); b.vel.y = 2; b.last = p; sound.touch(); return; }
      }
      b.owner = p; b.last = p; p.hold = 0; b.fire = 0; sound.touch();
      return;
    }
  }

  private onGoal(team: number) {
    const tm = this.teams[team]; tm.score++;
    this.state = 'goal'; this.stateT = 0;
    const last = this.ball.last, own = !!last && last.team !== team;
    this.scorer = last && !own ? last : this.players.find(p => p.team === team && p.role === 'att')!;
    for (const p of this.players) if (p.team === team && p.role !== 'gk') p.celebrate = 3.4;
    this.ev.goal(team, own ? 'Gol en propia' : `Dorsal ${this.scorer.num * 4 + 3}`);
    this.ev.shake(0.6);
    if (!this.attract) { sound.whistle(1); if (team === 0) sound.cheer(); else sound.groan(); }
  }

  private applyPower(kind: PowerKind, p: Player) {
    const tm = this.teams[p.team];
    if (kind === 'turbo') tm.turbo = 7; else if (kind === 'fuego') tm.fire = true; else tm.giant = 10;
    sound.pickup();
    this.fx.burst(p.pos.clone().setY(1), 30, [POWER_INFO[kind].color, '#ffffff'], 6, 4, 0.8, 0.5);
    if (!this.attract) this.ev.toast(p.team === 0 ? POWER_INFO[kind].name : `Rival: ${POWER_INFO[kind].name}`, p.team === 0 ? POWER_INFO[kind].color : '#ff3b4f');
  }
}

import * as THREE from 'three';
import { Kit } from './config';
import { lin } from './three-compat';

// Jugador low-poly articulado (piernas, brazos, cabeza) con animaciones procedurales.
export type Role = 'gk' | 'def' | 'att';
const SKINS = ['#f1c7a3', '#d9a27a', '#a8714c', '#7a4a2e'];
const HAIR = ['#1a1410', '#3b2414', '#d9b25a', '#0d0d0d', '#7a3b1a'];

const box = (w: number, h: number, d: number, mat: THREE.Material, x: number, y: number, z = 0) => {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat); m.position.set(x, y, z); return m;
};

export class Player {
  readonly group = new THREE.Group();
  private body = new THREE.Group();
  private legs: THREE.Group[] = [];
  private arms: THREE.Group[] = [];
  readonly marker: THREE.Mesh;
  pos = new THREE.Vector3();
  vel = new THREE.Vector3();
  want = new THREE.Vector3();         // velocidad deseada (la fija IA o jugador)
  face = new THREE.Vector3(1, 0, 0);  // dirección a la que mira
  home = new THREE.Vector3();
  kickCd = 0; stun = 0; slide = 0; kickAnim = 0; celebrate = 0; dive = 0; diveSide = 0; hold = 0; think = 0;
  scale = 1; sprinting = false;
  private phase = Math.random() * 6;

  constructor(scene: THREE.Object3D, readonly team: number, readonly role: Role, kit: Kit, readonly num: number, shadowMat: THREE.Material) {
    const gk = role === 'gk';
    const shirt = new THREE.MeshLambertMaterial({ color: lin(gk ? kit.gk : kit.shirt), emissive: lin(gk ? kit.gk : kit.shirt).multiplyScalar(0.18) });
    const shorts = new THREE.MeshLambertMaterial({ color: lin(gk ? '#1a1d2a' : kit.shorts) });
    const socks = new THREE.MeshLambertMaterial({ color: lin(gk ? kit.gk : kit.socks) });
    const skin = new THREE.MeshLambertMaterial({ color: lin(SKINS[(num * 3 + team) % SKINS.length]) });
    const boot = new THREE.MeshLambertMaterial({ color: lin(team ? '#ffd23f' : '#c6ff3d') });
    const hair = new THREE.MeshLambertMaterial({ color: lin(HAIR[(num * 2 + team * 3) % HAIR.length]) });
    const glove = new THREE.MeshLambertMaterial({ color: lin('#f5f5f5') });

    this.body.add(box(0.56, 0.6, 0.32, shirt, 0, 1.2));
    this.body.add(box(0.5, 0.26, 0.32, shorts, 0, 0.84));
    const head = new THREE.Mesh(new THREE.IcosahedronGeometry(0.19, 1), skin); head.position.y = 1.72; this.body.add(head);
    this.body.add(box(0.34, 0.12, 0.36, hair, 0, 1.86, -0.02));
    this.body.add(box(0.26, 0.08, 0.04, shirt, 0, 1.52, 0.15));
    for (const s of [-1, 1]) {
      const leg = new THREE.Group(); leg.position.set(s * 0.13, 0.86, 0);
      leg.add(box(0.2, 0.4, 0.22, shorts, 0, -0.16));
      leg.add(box(0.16, 0.42, 0.18, socks, 0, -0.55));
      leg.add(box(0.18, 0.12, 0.32, boot, 0, -0.8, 0.06));
      this.body.add(leg); this.legs.push(leg);
      const arm = new THREE.Group(); arm.position.set(s * 0.36, 1.46, 0);
      arm.add(box(0.15, 0.26, 0.16, shirt, 0, -0.12));
      arm.add(box(0.12, 0.34, 0.13, skin, 0, -0.42));
      arm.add(box(0.15, 0.13, 0.15, gk ? glove : skin, 0, -0.62));
      this.body.add(arm); this.arms.push(arm);
    }
    this.group.add(this.body);
    // Sombras múltiples (una por torre de focos) bajo los pies.
    const sg = new THREE.PlaneGeometry(0.75, 2.2); sg.translate(0, 1.0, 0); sg.rotateX(-Math.PI / 2);
    for (let i = 0; i < 4; i++) {
      const s = new THREE.Mesh(sg, shadowMat); s.position.y = 0.02 + i * 0.002; s.rotation.y = Math.PI / 4 + i * Math.PI / 2; this.group.add(s);
    }
    this.marker = new THREE.Mesh(new THREE.TorusGeometry(0.62, 0.07, 6, 28), new THREE.MeshBasicMaterial({ color: lin('#ffe53b') }));
    this.marker.rotation.x = Math.PI / 2; this.marker.position.y = 0.06; this.marker.visible = false;
    this.group.add(this.marker);
    scene.add(this.group);
  }

  reset(p: THREE.Vector3, faceX: number) {
    this.pos.copy(p); this.vel.set(0, 0, 0); this.want.set(0, 0, 0); this.face.set(faceX, 0, 0);
    this.kickCd = 0.3; this.stun = 0; this.slide = 0; this.kickAnim = 0; this.celebrate = 0; this.dive = 0; this.hold = 0;
  }

  animate(dt: number, t: number) {
    const sp = Math.hypot(this.vel.x, this.vel.z), k = Math.min(1, sp / 6.5);
    this.phase += dt * (3 + sp * 1.6);
    const sw = Math.sin(this.phase) * 0.95 * k;
    this.group.position.copy(this.pos);
    this.group.rotation.y = Math.atan2(this.face.x, this.face.z);
    this.group.scale.setScalar(this.scale);
    const b = this.body;
    b.position.set(0, Math.abs(Math.cos(this.phase)) * 0.08 * k, 0);
    b.rotation.set(0.12 * k + (this.sprinting ? 0.12 : 0), 0, 0);
    this.legs[0].rotation.set(sw, 0, 0); this.legs[1].rotation.set(-sw, 0, 0);
    this.arms[0].rotation.set(-sw * 0.8, 0, -0.12); this.arms[1].rotation.set(sw * 0.8, 0, 0.12);
    if (this.kickAnim > 0) {
      const a = 1 - this.kickAnim; // 0 → 1
      this.legs[1].rotation.x = a < 0.35 ? (a / 0.35) * 0.9 : 0.9 - ((a - 0.35) / 0.65) * 2.6;
      this.arms[0].rotation.x = -0.9; this.arms[1].rotation.z = 0.9;
      b.rotation.x = -0.15;
    }
    if (this.slide > 0) {
      b.position.y = -0.55; b.rotation.x = -1.15;
      this.legs[0].rotation.x = -0.4; this.legs[1].rotation.x = 0.3; this.arms[0].rotation.z = -1.2; this.arms[1].rotation.z = 1.2;
    }
    if (this.dive > 0) {
      const d = Math.min(1, this.dive * 2.2);
      b.rotation.set(0, 0, -this.diveSide * 1.3 * d); b.position.y = 0.45 * d;
      this.arms[0].rotation.set(0, 0, -2.8); this.arms[1].rotation.set(0, 0, 2.8);
    }
    if (this.stun > 0) { b.rotation.x = 0.5; b.rotation.z = Math.sin(t * 20) * 0.15; }
    if (this.celebrate > 0) {
      b.position.y = Math.abs(Math.sin(t * 7)) * 0.55;
      this.arms[0].rotation.set(-2.9, 0, -0.4 + Math.sin(t * 12) * 0.3); this.arms[1].rotation.set(-2.9, 0, 0.4 - Math.sin(t * 12) * 0.3);
      this.legs[0].rotation.x = 0.3; this.legs[1].rotation.x = -0.3;
    }
    this.marker.rotation.z = t * 2;
  }
}

import * as THREE from 'three';
import { POWER_INFO, PowerKind } from './config';
import type { Player } from './players';
import { lin, radialTexture } from './three-compat';

// Power-ups flotantes con columna de luz: turbo, tiro de fuego y portero gigante.
const KINDS: PowerKind[] = ['turbo', 'fuego', 'muro'];

export class PowerUps {
  private group = new THREE.Group();
  private core: THREE.Mesh;
  private ring: THREE.Mesh;
  private glow: THREE.Sprite;
  private beam: THREE.Mesh;
  private mats: THREE.MeshBasicMaterial[];
  active: PowerKind | null = null;
  pos = new THREE.Vector3();
  private timer = 6;
  private life = 0;

  constructor(scene: THREE.Object3D) {
    const coreMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.9 });
    const beamMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false });
    this.mats = [coreMat, ringMat, beamMat];
    this.core = new THREE.Mesh(new THREE.OctahedronGeometry(0.42, 0), coreMat);
    this.ring = new THREE.Mesh(new THREE.TorusGeometry(0.72, 0.06, 6, 30), ringMat);
    this.beam = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 0.75, 9, 16, 1, true), beamMat);
    this.beam.position.y = 4.5;
    this.glow = new THREE.Sprite(new THREE.SpriteMaterial({
      map: radialTexture([[0, 'rgba(255,255,255,1)'], [0.3, 'rgba(255,255,255,0.45)'], [1, 'rgba(255,255,255,0)']]),
      blending: THREE.AdditiveBlending, transparent: true, depthWrite: false,
    }));
    this.glow.scale.set(3.2, 3.2, 1);
    this.group.add(this.core, this.ring, this.beam, this.glow);
    this.group.visible = false;
    scene.add(this.group);
  }

  private spawn() {
    this.active = KINDS[(Math.random() * KINDS.length) | 0];
    this.pos.set((Math.random() - 0.5) * 36, 0, (Math.random() - 0.5) * 24);
    const c = lin(POWER_INFO[this.active].color);
    this.mats.forEach(m => m.color.copy(c));
    (this.glow.material as THREE.SpriteMaterial).color.copy(c);
    this.group.position.copy(this.pos); this.group.visible = true; this.life = 14;
  }

  clear() { this.active = null; this.group.visible = false; this.timer = 8; }

  /** Devuelve quién recogió el power-up este frame (si alguien lo hizo). */
  update(dt: number, t: number, players: Player[], live: boolean): { kind: PowerKind; p: Player } | null {
    if (!this.active) {
      if (live) { this.timer -= dt; if (this.timer <= 0) this.spawn(); }
      return null;
    }
    this.life -= dt;
    this.core.position.y = 1.1 + Math.sin(t * 3) * 0.18; this.core.rotation.y = t * 2.5;
    this.ring.position.y = this.core.position.y; this.ring.rotation.set(Math.PI / 2 + Math.sin(t) * 0.3, 0, t);
    this.glow.position.y = this.core.position.y;
    this.group.visible = this.life > 3 || Math.sin(t * 20) > 0;
    if (this.life <= 0) { this.clear(); return null; }
    if (!live) return null;
    for (const p of players) {
      if (p.role === 'gk' || p.stun > 0) continue;
      if (Math.hypot(p.pos.x - this.pos.x, p.pos.z - this.pos.z) < 1.15) {
        const kind = this.active; this.clear(); this.timer = 10 + Math.random() * 6;
        return { kind, p };
      }
    }
    return null;
  }
}

import * as THREE from 'three';
import { FIELD } from './config';
import { canvasTexture, lin, radialTexture, rawColor } from './three-compat';

// Estadio nocturno: cielo, césped a franjas con líneas, porterías con red, vallas LED, gradas y torres de focos.
const { L, W, GW, GH, GD } = FIELD;
export const FOG_HEX = '#0b1230';
export const STAND_FAR = W + 4.2;   // inicio de la grada lateral (z negativa)
export const STAND_END = L + 5.2;   // inicio de las gradas de fondo

function pitchTexture() {
  const MX = L + 5, MZ = W + 4, S = 2048 / (MX * 2), H = Math.round(MZ * 2 * S);
  return canvasTexture(2048, H, g => {
    const X = (x: number) => (x + MX) * S, Z = (z: number) => (z + MZ) * S;
    g.fillStyle = '#1d6b2e'; g.fillRect(0, 0, 2048, H);
    for (let i = 0; i < 14; i++) { // franjas de cortadora
      g.fillStyle = i % 2 ? '#227a35' : '#1b6229';
      g.fillRect(X(-MX + i * (MX * 2 / 14)), 0, MX * 2 / 14 * S + 1, H);
    }
    for (let i = 0; i < 9000; i++) { // textura de hierba
      g.fillStyle = `rgba(${Math.random() < 0.5 ? '0,0,0' : '170,255,170'},${Math.random() * 0.06})`;
      g.fillRect(Math.random() * 2048, Math.random() * H, 2, 2 + Math.random() * 3);
    }
    for (const [cx, cz] of [[-L, -W], [L, -W], [-L, W], [L, W], [0, 0]]) { // charcos de luz de los focos
      const gr = g.createRadialGradient(X(cx * 0.55), Z(cz * 0.55), 0, X(cx * 0.55), Z(cz * 0.55), 26 * S);
      gr.addColorStop(0, 'rgba(230,255,220,0.13)'); gr.addColorStop(1, 'rgba(230,255,220,0)');
      g.fillStyle = gr; g.fillRect(0, 0, 2048, H);
    }
    g.strokeStyle = 'rgba(255,255,255,0.92)'; g.lineWidth = 0.13 * S; g.fillStyle = 'rgba(255,255,255,0.92)';
    const rect = (x0: number, z0: number, x1: number, z1: number) => g.strokeRect(X(x0), Z(z0), (x1 - x0) * S, (z1 - z0) * S);
    rect(-L, -W, L, W);
    g.beginPath(); g.moveTo(X(0), Z(-W)); g.lineTo(X(0), Z(W)); g.stroke();
    g.beginPath(); g.arc(X(0), Z(0), 5 * S, 0, Math.PI * 2); g.stroke();
    for (const s of [-1, 1]) {
      const a = s * L, b = s * (L - 7), c = s * (L - 2.6);
      rect(Math.min(a, b), -9, Math.max(a, b), 9);
      rect(Math.min(a, c), -5.4, Math.max(a, c), 5.4);
      g.beginPath(); g.arc(X(s * (L - 5.2)), Z(0), 0.22 * S, 0, Math.PI * 2); g.fill();
      g.beginPath(); g.arc(X(s * (L - 5.2)), Z(0), 4.2 * S, s > 0 ? Math.PI * 0.62 : -Math.PI * 0.38, s > 0 ? Math.PI * 1.38 : Math.PI * 0.38); g.stroke();
      for (const t of [-1, 1]) { g.beginPath(); g.arc(X(a), Z(t * W), 1 * S, 0, Math.PI * 2); g.stroke(); }
    }
    g.beginPath(); g.arc(X(0), Z(0), 0.25 * S, 0, Math.PI * 2); g.fill();
  });
}

function goal(side: number, netMat: THREE.Material, postMat: THREE.Material) {
  const grp = new THREE.Group(); grp.position.x = side * L;
  const post = new THREE.CylinderGeometry(0.09, 0.09, GH, 10);
  for (const z of [-GW, GW]) { const m = new THREE.Mesh(post, postMat); m.position.set(0, GH / 2, z); grp.add(m); }
  const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, GW * 2 + 0.18, 10), postMat);
  bar.rotation.x = Math.PI / 2; bar.position.y = GH; grp.add(bar);
  const net = new THREE.Group(); grp.add(net);
  const back = new THREE.Mesh(new THREE.PlaneGeometry(GW * 2, GH), netMat);
  back.rotation.y = Math.PI / 2; back.position.set(side * GD, GH / 2, 0); net.add(back);
  const top = new THREE.Mesh(new THREE.PlaneGeometry(GD, GW * 2), netMat);
  top.rotation.x = -Math.PI / 2; top.position.set(side * GD / 2, GH, 0); net.add(top);
  for (const z of [-GW, GW]) {
    const s = new THREE.Mesh(new THREE.PlaneGeometry(GD, GH), netMat); s.position.set(side * GD / 2, GH / 2, z); net.add(s);
  }
  return { grp, back };
}

function standGeometry(rows: number, length: number) {
  const sh = new THREE.Shape(); sh.moveTo(0, 0);
  for (let r = 0; r < rows; r++) { sh.lineTo(r * 0.85, 0.6 + r * 0.55); sh.lineTo((r + 1) * 0.85, 0.6 + r * 0.55); }
  sh.lineTo(rows * 0.85 + 1.5, 0.6 + rows * 0.55 + 2.2); sh.lineTo(rows * 0.85 + 1.5, 0); sh.lineTo(0, 0);
  const g = new THREE.ExtrudeGeometry(sh, { depth: length, bevelEnabled: false });
  g.translate(0, 0, -length / 2); return g;
}

export function buildStadium(scene: THREE.Scene) {
  const root = new THREE.Group(); scene.add(root);
  // Cielo con degradado y estrellas.
  const sky = new THREE.Mesh(new THREE.SphereGeometry(400, 24, 12), new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false,
    uniforms: { top: { value: rawColor('#02040c') }, hor: { value: rawColor('#1a2458') } },
    vertexShader: 'varying float h; void main(){ h = normalize(position).y; gl_Position = projectionMatrix*modelViewMatrix*vec4(position,1.0); }',
    fragmentShader: 'uniform vec3 top; uniform vec3 hor; varying float h; void main(){ gl_FragColor = vec4(mix(hor, top, pow(clamp(h*1.6,0.0,1.0),0.6)),1.0); }',
  }));
  root.add(sky);
  const sp = new Float32Array(900);
  for (let i = 0; i < 300; i++) {
    const a = Math.random() * Math.PI * 2, e = 0.15 + Math.random() * 1.2;
    sp.set([Math.cos(a) * Math.cos(e) * 380, Math.sin(e) * 380, Math.sin(a) * Math.cos(e) * 380], i * 3);
  }
  const sg = new THREE.BufferGeometry(); sg.setAttribute('position', new THREE.BufferAttribute(sp, 3));
  root.add(new THREE.Points(sg, new THREE.PointsMaterial({ color: 0xffffff, size: 1.6, sizeAttenuation: false, fog: false })));

  // Césped y alrededores.
  const pitch = new THREE.Mesh(new THREE.PlaneGeometry((L + 5) * 2, (W + 4) * 2), new THREE.MeshLambertMaterial({ map: pitchTexture() }));
  pitch.rotation.x = -Math.PI / 2; root.add(pitch);
  const out = new THREE.Mesh(new THREE.PlaneGeometry(260, 200), new THREE.MeshLambertMaterial({ color: lin('#123a1d') }));
  out.rotation.x = -Math.PI / 2; out.position.y = -0.02; root.add(out);

  // Porterías.
  const netTex = canvasTexture(128, 128, g => {
    g.strokeStyle = 'rgba(255,255,255,0.95)'; g.lineWidth = 3;
    for (let i = 0; i <= 128; i += 16) { g.beginPath(); g.moveTo(i, 0); g.lineTo(i, 128); g.moveTo(0, i); g.lineTo(128, i); g.stroke(); }
  }, true);
  netTex.repeat.set(5, 3);
  const netMat = new THREE.MeshBasicMaterial({ map: netTex, transparent: true, opacity: 0.75, side: THREE.DoubleSide, depthWrite: false, color: lin('#dfe8ff') });
  const postMat = new THREE.MeshLambertMaterial({ color: 0xffffff, emissive: lin('#555a66') });
  const goals = [goal(-1, netMat, postMat), goal(1, netMat, postMat)];
  goals.forEach(g => root.add(g.grp));

  // Vallas LED con texto desplazándose.
  const led = canvasTexture(1024, 64, g => {
    g.fillStyle = '#05060f'; g.fillRect(0, 0, 1024, 64);
    const words = [['NONA', '#c6ff3d'], ['FÚTBOL ARCADE', '#ffffff'], ['¡GOL!', '#ff3b4f'], ['NONA FC', '#3b82ff']];
    g.font = 'italic 900 40px Arial Black, Impact, sans-serif'; g.textBaseline = 'middle';
    let x = 10; words.forEach(([w, c]) => { g.fillStyle = c; g.fillText(w, x, 34); x += g.measureText(w).width + 46; });
  }, true);
  const ledMat = new THREE.MeshBasicMaterial({ map: led, color: lin('#ffffff') });
  const boardGeoLong = new THREE.BoxGeometry(L * 2 + 8, 0.9, 0.2), boardGeoEnd = new THREE.BoxGeometry(0.2, 0.9, W * 2 + 2.6);
  const boards: THREE.Mesh[] = [];
  for (const s of [-1, 1]) {
    const b = new THREE.Mesh(boardGeoLong, ledMat); b.position.set(0, 0.45, s * (W + 1.6)); root.add(b); boards.push(b);
    const e = new THREE.Mesh(boardGeoEnd, ledMat); e.position.set(s * (L + GD + 1.2), 0.45, 0); root.add(e);
  }
  led.repeat.set(6, 1);

  // Gradas escalonadas.
  const standMat = new THREE.MeshLambertMaterial({ color: lin('#2a3050') });
  const far = new THREE.Mesh(standGeometry(13, L * 2 + 14), standMat);
  far.rotation.y = Math.PI / 2; far.position.set(0, 0, -STAND_FAR); root.add(far);
  for (const s of [-1, 1]) {
    const e = new THREE.Mesh(standGeometry(10, W * 2 + 8), standMat);
    e.rotation.y = s > 0 ? 0 : Math.PI; e.position.set(s * STAND_END, 0, 0); root.add(e);
  }
  // Techo con banda luminosa.
  const roofMat = new THREE.MeshLambertMaterial({ color: lin('#141830'), emissive: lin('#0a0d1c') });
  const roofZ = -STAND_FAR - 9, roofY = 11.8;
  const roof = new THREE.Mesh(new THREE.BoxGeometry(L * 2 + 16, 0.6, 9), roofMat); roof.position.set(0, roofY, roofZ); root.add(roof);
  const strip = new THREE.Mesh(new THREE.BoxGeometry(L * 2 + 16, 0.25, 0.25), new THREE.MeshBasicMaterial({ color: lin('#c6ff3d') }));
  strip.position.set(0, roofY - 0.4, roofZ + 4.5); root.add(strip);
  for (let x = -L - 6; x <= L + 6; x += 12) {
    const pil = new THREE.Mesh(new THREE.BoxGeometry(0.5, roofY, 0.5), roofMat); pil.position.set(x, roofY / 2, roofZ - 4); root.add(pil);
  }
  // Fila de focos en el borde del techo.
  const lampTex = radialTexture([[0, 'rgba(255,255,255,1)'], [0.2, 'rgba(230,240,255,0.7)'], [0.55, 'rgba(150,180,255,0.15)'], [1, 'rgba(120,150,255,0)']]);
  const lampMat = new THREE.SpriteMaterial({ map: lampTex, color: lin('#e6eeff'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: false });
  const lampBox = new THREE.BoxGeometry(1.4, 0.5, 0.4), lampBoxMat = new THREE.MeshBasicMaterial({ color: lin('#f4f8ff'), fog: false });
  for (let x = -L - 3; x <= L + 3; x += 5.5) {
    const lb = new THREE.Mesh(lampBox, lampBoxMat); lb.position.set(x, roofY - 0.7, roofZ + 4.4); root.add(lb);
    const sp = new THREE.Sprite(lampMat); sp.scale.set(7, 7, 1); sp.position.set(x, roofY - 0.7, roofZ + 4.8); root.add(sp);
  }
  // Torres de focos con halo y haz de luz.
  const glowTex = radialTexture([[0, 'rgba(255,255,255,1)'], [0.18, 'rgba(235,245,255,0.75)'], [0.5, 'rgba(160,190,255,0.18)'], [1, 'rgba(120,150,255,0)']]);
  const panelTex = canvasTexture(128, 64, g => {
    g.fillStyle = '#1b2033'; g.fillRect(0, 0, 128, 64);
    for (let y = 0; y < 3; y++) for (let x = 0; x < 6; x++) {
      const gr = g.createRadialGradient(12 + x * 21, 11 + y * 21, 0, 12 + x * 21, 11 + y * 21, 10);
      gr.addColorStop(0, '#ffffff'); gr.addColorStop(0.6, '#e8f2ff'); gr.addColorStop(1, '#6a7aa8');
      g.fillStyle = gr; g.beginPath(); g.arc(12 + x * 21, 11 + y * 21, 9, 0, Math.PI * 2); g.fill();
    }
  });
  const poleMat = new THREE.MeshLambertMaterial({ color: lin('#3b4160') });
  const beamMat = new THREE.MeshBasicMaterial({ color: lin('#9fb8ff'), transparent: true, opacity: 0.05, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, fog: false });
  for (const [x, z] of [[-L - 9, -W - 12], [L + 9, -W - 12], [-L - 9, W + 9], [L + 9, W + 9]]) {
    const h = 26;
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.6, h, 8), poleMat); pole.position.set(x, h / 2, z); root.add(pole);
    const head = new THREE.Group(); head.position.set(x, h + 1.5, z); head.lookAt(0, 0, 0); root.add(head);
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(6, 3), new THREE.MeshBasicMaterial({ map: panelTex, fog: false }));
    panel.position.z = 0.3; head.add(panel);
    const backBox = new THREE.Mesh(new THREE.BoxGeometry(6.3, 3.3, 0.5), poleMat); head.add(backBox);
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: lin('#dfe9ff'), blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: false }));
    glow.scale.set(26, 26, 1); glow.position.set(x * 0.98, h + 1.5, z * 0.98); root.add(glow);
    const len = Math.hypot(x, h, z) * 0.95;
    const cone = new THREE.ConeGeometry(13, len, 24, 1, true); cone.translate(0, -len / 2, 0); cone.rotateX(-Math.PI / 2);
    const beam = new THREE.Mesh(cone, beamMat); beam.position.copy(head.position); beam.lookAt(x * 0.15, 0, z * 0.15); root.add(beam);
  }

  let t = 0;
  const nets = [0, 0];
  return {
    root,
    shakeNet(side: number) { nets[side > 0 ? 1 : 0] = 1; },
    update(dt: number) {
      t += dt; led.offset.x = (t * 0.05) % 1;
      goals.forEach((g, i) => {
        nets[i] = Math.max(0, nets[i] - dt * 1.4);
        const k = nets[i] * Math.sin(t * 30) * 0.25 + nets[i] * 0.35;
        g.back.position.x = (i ? 1 : -1) * (GD + k);
