import * as THREE from 'three';

// r170 gestiona el color y r128 no: lo desactivamos y linealizamos a mano con lin() → mismo aspecto en ambas.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

/** Color sRGB (#hex) → lineal para materiales, luces, niebla y partículas. */
export const lin = (c: string | THREE.Color) => new THREE.Color(c).convertSRGBToLinear();

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Color hex → vector sRGB "crudo" para shaders propios (se muestra igual en r128 y r170). */
export function rawColor(hex: string) {
  const v = parseInt(hex.replace('#', ''), 16);
  return new THREE.Vector3(((v >> 16) & 255) / 255, ((v >> 8) & 255) / 255, (v & 255) / 255);
}

/** Textura a partir de un canvas 2D dibujado al vuelo. */
export function canvasTexture(w: number, h: number, draw: (g: CanvasRenderingContext2D) => void, repeat = false) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d')!);
  const t = new THREE.CanvasTexture(c);
  if (repeat) { t.wrapS = THREE.RepeatWrapping; t.wrapT = THREE.RepeatWrapping; }
  t.anisotropy = 4;
  return srgbTexture(t);
}

/** Degradado radial (halos, sombras, chispas). */
export function radialTexture(stops: Array<[number, string]>, size = 64) {
  return canvasTexture(size, size, g => {
    const h = size / 2, gr = g.createRadialGradient(h, h, 0, h, h, h);
    stops.forEach(([o, c]) => gr.addColorStop(o, c));
    g.fillStyle = gr; g.fillRect(0, 0, size, size);
  });
}

